questionvariables.text:
Srx: matrix([1,0],[0,-1]); Sry: matrix([-1,0],[0,1]); Sryx: matrix([0,1],[1,0]); Srmyx: matrix([0,-1],[-1,0]);
Sr90: matrix([0,-1],[1,0]); Sr180: matrix([-1,0],[0,-1]); Sr270: matrix([0,1],[-1,0]);
symkeys: ["rx","ry","ryx","rmyx","r90","r180","r270"];
symmats: [Srx,Sry,Sryx,Srmyx,Sr90,Sr180,Sr270];
sm(k) := symmats[sublist_indices(symkeys, lambda([u], u=k))[1]];
sn(k) := sublist_indices(symkeys, lambda([u], u=k))[1];
skey(A) := block([j], j: sublist_indices(symmats, lambda([u], is(u=A))), if j=[] then "none" else symkeys[j[1]]);
/* Design: classify-the-objects pattern: describe the transformation from its matrix. Source: adapted from SMP Book 5 (Metric), Chapter 14, Exercise B, question 1. Fixed option order; the first option (the identity) is never correct, as no identity matrix is shown. Every key appears at least 4 times in at least 3 positions. */
klist: [["r180","ry","rx","r270"],["r270","r90","ryx","r180"],["rx","ryx","r180","rmyx"],["rx","ry","r270","r90"],["rmyx","ry","ryx","rx"],["r90","r180","rx","ry"],["rx","r270","rmyx","ry"],["ry","rx","r180","rmyx"],["ryx","r270","r180","r90"],["r90","r180","ryx","ry"]];
ix: 1+rand(10);
K: klist[ix];
dgk: ["ry","rx","rmyx","ryx","r270","rmyx","r90"];
K1: K[1]; M1: sm(K1);
opt1: [["id1", false, "the identity (no change)"], ["rx1", is(K[1]="rx"), "reflection in the x-axis"], ["ry1", is(K[1]="ry"), "reflection in the y-axis"], ["ryx1", is(K[1]="ryx"), "reflection in the line y = x"], ["rmyx1", is(K[1]="rmyx"), "reflection in the line y = −x"], ["r901", is(K[1]="r90"), "rotation of 90° anticlockwise about O"], ["r1801", is(K[1]="r180"), "rotation of 180° about O"], ["r2701", is(K[1]="r270"), "rotation of 90° clockwise about O"]];
ta1: first(mcq_correct(opt1));
dg1: opt1[1+sn(dgk[sn(K1)])][1];
gw1: opt1[1][1];
K2: K[2]; M2: sm(K2);
opt2: [["id2", false, "the identity (no change)"], ["rx2", is(K[2]="rx"), "reflection in the x-axis"], ["ry2", is(K[2]="ry"), "reflection in the y-axis"], ["ryx2", is(K[2]="ryx"), "reflection in the line y = x"], ["rmyx2", is(K[2]="rmyx"), "reflection in the line y = −x"], ["r902", is(K[2]="r90"), "rotation of 90° anticlockwise about O"], ["r1802", is(K[2]="r180"), "rotation of 180° about O"], ["r2702", is(K[2]="r270"), "rotation of 90° clockwise about O"]];
ta2: first(mcq_correct(opt2));
dg2: opt2[1+sn(dgk[sn(K2)])][1];
gw2: opt2[1][1];
K3: K[3]; M3: sm(K3);
opt3: [["id3", false, "the identity (no change)"], ["rx3", is(K[3]="rx"), "reflection in the x-axis"], ["ry3", is(K[3]="ry"), "reflection in the y-axis"], ["ryx3", is(K[3]="ryx"), "reflection in the line y = x"], ["rmyx3", is(K[3]="rmyx"), "reflection in the line y = −x"], ["r903", is(K[3]="r90"), "rotation of 90° anticlockwise about O"], ["r1803", is(K[3]="r180"), "rotation of 180° about O"], ["r2703", is(K[3]="r270"), "rotation of 90° clockwise about O"]];
ta3: first(mcq_correct(opt3));
dg3: opt3[1+sn(dgk[sn(K3)])][1];
gw3: opt3[1][1];
K4: K[4]; M4: sm(K4);
opt4: [["id4", false, "the identity (no change)"], ["rx4", is(K[4]="rx"), "reflection in the x-axis"], ["ry4", is(K[4]="ry"), "reflection in the y-axis"], ["ryx4", is(K[4]="ryx"), "reflection in the line y = x"], ["rmyx4", is(K[4]="rmyx"), "reflection in the line y = −x"], ["r904", is(K[4]="r90"), "rotation of 90° anticlockwise about O"], ["r1804", is(K[4]="r180"), "rotation of 180° about O"], ["r2704", is(K[4]="r270"), "rotation of 90° clockwise about O"]];
ta4: first(mcq_correct(opt4));
dg4: opt4[1+sn(dgk[sn(K4)])][1];
gw4: opt4[1][1];

feedbackvariables.text:
ci: sublist_indices(map(first, opt1), lambda([u], is(u=ans1)))[1];
ck: if ci=1 then "id" else symkeys[ci-1];
Cm: if ci=1 then matrix([1,0],[0,1]) else symmats[ci-1];

ci: sublist_indices(map(first, opt2), lambda([u], is(u=ans2)))[1];
ck: if ci=1 then "id" else symkeys[ci-1];
Cm: if ci=1 then matrix([1,0],[0,1]) else symmats[ci-1];

ci: sublist_indices(map(first, opt3), lambda([u], is(u=ans3)))[1];
ck: if ci=1 then "id" else symkeys[ci-1];
Cm: if ci=1 then matrix([1,0],[0,1]) else symmats[ci-1];

ci: sublist_indices(map(first, opt4), lambda([u], is(u=ans4)))[1];
ck: if ci=1 then "id" else symkeys[ci-1];
Cm: if ci=1 then matrix([1,0],[0,1]) else symmats[ci-1];
